def compute(vars):
    net_income_after_taxes = vars["Net Income After Taxes (NIAT)"]
    revenue = vars["Revenue"]
    multiplier = 100.0

    if revenue == 0:
        return {"value": None, "trace": {
            "Net Income After Taxes (NIAT)": net_income_after_taxes,
            "Revenue": revenue,
            "100": multiplier,
            "output_meta": {"currency": None, "scale": None, "unit": "percentage"},
        }}

    value = (net_income_after_taxes / revenue) * multiplier
    return {
        "value": value,
        "trace": {
            "Net Income After Taxes (NIAT)": net_income_after_taxes,
            "Revenue": revenue,
            "100": multiplier,
            "output_meta": {"currency": None, "scale": None, "unit": "percentage"},
        },
    }
